    """Parse a non-streaming JSON response from the LLM API."""
    try:
        result = resp.json()
    except json.JSONDecodeError as e:
        raise RuntimeError(f"LLM API returned non-JSON response: {resp.text[:500]}") from e
    choices = result.get("choices")
